import Dispatch
func refreshOne(done: @escaping () -> Void) {
    let worker = DispatchQueue(label: "garden.cards")
    let group = DispatchGroup()
    for id in [71] {
        group.enter()
        worker.async {
            defer { group.leave() }
            print("Карточка \(id)")
        }
    }
    group.notify(queue: .main) {
        print("Панель готова")
        done()
    }
}

Вывод «Карточка 71», «Панель готова», затем done. enter() и leave() относятся к реальной работе одной карточки.

