import Dispatch
func inspectPending(done: @escaping () -> Void) {
    DispatchQueue.global().async {
        let group = DispatchGroup()
        group.enter()
        let status = group.wait(timeout: .now())
        print(status == .timedOut)
        group.leave()
        group.notify(queue: .main) { done() }
    }
}

Вывод true, затем done на main. Проверка известного незавершённого учёта происходит в фоне, timeout не отменяет его.

